export function getPostCategories(post: any, dlCategoryMap: Record<string, string[]> = {}): string[] {
  if (!post) return ['Linux'];
  
  const slug = post.link_slug || post.slug || String(post.id || '');
  const idStr = String(post.id || '');

  // 1. Check if explicitly saved in dlCategoryMap by slug or ID
  if (slug && Array.isArray(dlCategoryMap[slug]) && dlCategoryMap[slug].length > 0) {
    return dlCategoryMap[slug];
  }
  if (idStr && Array.isArray(dlCategoryMap[idStr]) && dlCategoryMap[idStr].length > 0) {
    return dlCategoryMap[idStr];
  }

  // 2. Fallback to keyword-based smart auto-categorization
  const text = `${post.title || ''} ${post.description || ''} ${post.summary || ''}`.toLowerCase();
  const cats: string[] = [];
  if (text.includes('vps') || text.includes('host') || text.includes('server') || text.includes('ssh')) {
    cats.push('VPS & Hosting');
  }
  if (text.includes('linux') || text.includes('ubuntu') || text.includes('nginx') || text.includes('debian') || text.includes('bash') || text.includes('systemd')) {
    cats.push('Linux');
  }
  if (text.includes('docker') || text.includes('container') || text.includes('cloud') || text.includes('aws') || text.includes('deploy')) {
    cats.push('Cloud');
  }
  if (text.includes('https') || text.includes('ssl') || text.includes('cert') || text.includes('security') || text.includes('firewall') || text.includes('wireguard') || text.includes('vpn')) {
    cats.push('Cybersecurity');
  }
  if (text.includes('domain') || text.includes('dns') || text.includes('web') || text.includes('proxy') || text.includes('php') || text.includes('react') || text.includes('javascript') || text.includes('node')) {
    cats.push('Web Development');
  }
  if (text.includes('ai') || text.includes('llm') || text.includes('gpt') || text.includes('bot')) {
    cats.push('AI');
  }
  if (text.includes('error') || text.includes('fix') || text.includes('troubleshoot') || text.includes('debug') || text.includes('guide')) {
    cats.push('Troubleshooting');
  }

  return cats.length > 0 ? cats : ['Linux'];
}


